function scenarioInner(){const d=scenarioData();return `<div class="scenario-top"><div class="inline"><div class="window-dots"><span></span><span></span><span></span></div><span class="small-label">${tr('Pregled kreditnog portfolija','Loan portfolio review')}</span></div>${tag(tr('SINTETIČKI PODACI','SYNTHETIC DATA'),'warm')}</div><div class="scenario-toolbar" role="group" aria-label="${tr('Faza ilustracije','Illustration stage')}">${[tr('1 · Priprema','1 · Prepared'),tr('2 · Zaustavljanje','2 · Stopped'),tr('3 · Novo izvršenje','3 · New run')].map((s,i)=>`<button data-action="scenario" data-value="${i}" aria-pressed="${scenario===i}">${s}</button>`).join('')}<button class="play-btn" data-action="play" aria-label="${tr(playing?'Pauziraj ilustraciju':'Pokreni ilustraciju',playing?'Pause illustration':'Play illustration')}" title="${tr(playing?'Pauziraj':'Pokreni animaciju',playing?'Pause':'Play animation')}">${icon(playing?'pause':'play')}</button></div><div class="scenario-inner"><div class="scenario-status"><h3>${d.title}</h3>${tag(d.badge,d.kind)}</div><div class="metrics3"><div class="metric"><div class="metric-value">${d.total}</div><label>${tr('očekivanih računa','expected accounts')}</label></div><div class="metric"><div class="metric-value ${scenario===1?'red':scenario===2?'accent':'warm'}">${d.missing}</div><label>${tr('nedostaje u pregledu','missing from report')}</label></div><div class="metric"><div class="metric-value ${scenario===0?'warm':'accent'}">${d.ready}</div><label>${tr('računa u pregledu','accounts in report')}</label></div></div><div class="quality-track" aria-hidden="true"><span style="width:${scenario===0?'0':scenario===1?'98.8':'100'}%"></span></div><div class="scenario-lines">${[tr('Obrada podataka','Data processing'),tr('Obavezna provera','Required check'),tr('Naredni korak toka','Next workflow step')].map((l,i)=>`<div class="scenario-line"><span>${l}</span><span class="outcome ${d.states[i]}">${icon(d.states[i]==='ok'?'checkcircle':d.states[i]==='fail'?'stop':'clock')}${d.lines[i]}</span></div>`).join('')}</div><div class="scenario-history">${icon('history')}<span>${d.history}</span></div></div>`;}
function scenarioAside(){const d=scenarioData();return `<div class="story-copy"><span class="small-label">${tr('Isti proces · tri poslovna pogleda','One process · three business views')}</span><h3>${d.head}</h3><p>${d.desc}</p></div><div class="role-list">${[tr('Uprava','Leadership'),tr('Rukovodilac','Process manager'),tr('Operativni tim','Operations team')].map((r,i)=>`<div class="role-item">${icon(['chart','users','search'][i])}<div><strong>${r}</strong><p>${d.roles[i]}</p></div></div>`).join('')}</div><div class="case-mini-links">${smallLink(tr('Bankarski primer','Banking example'),'case','bank')}${smallLink(tr('Lanac snabdevanja','Supply chain'),'case','supply')}</div>`;}
function slide5(){const controls=[
 ['Obuhvat','Scope','Koji podaci i rezultat pripadaju ovom zadatku?','Which data and result belong to this task?','Projekat, resurs i odobrena polja.','Project, resource and approved fields.'],
 ['Ovlašćenje','Authority','Ko sme da traži radnju i kada treba potvrda?','Who may request an action and when is confirmation required?','Aktuelna prava i potvrde podržanih radnji.','Current permissions and confirmations for supported actions.'],
 ['Verzija','Version','Po kojoj definiciji se posao izvršava?','Which definition does the work execute against?','Zabeležena verzija posla, izveštaja ili odobrenog plana.','Recorded job, report or approved-plan version.'],
 ['Ishod i dokaz','Outcome and evidence','Šta je stvarno izvršeno i šta rezultat potvrđuje?','What actually ran and what does the result establish?','Status, referenca i raspoloživa evidencija.','Status, reference and available evidence.'],
 ['Oporavak','Recovery','Šta ako pokušaj ne uspe ili ishod nije poznat?','What if an attempt fails or its outcome is unknown?','Trajno stanje i ograničen oporavak podržanih procesa.','Durable state and bounded recovery for supported processes.']
 ];return head(tr('05 / Osnova prednosti','05 / The basis of differentiation'),tr('Tim vidi šta je dozvoljeno<br><em>i šta je zaista izvršeno.</em>','Teams see what is permitted<br><em>and what actually ran.</em>'),tr('Za podržane radnje povezuju se dozvole, korišćena verzija i evidencija ishoda, bilo da posao pokreće korisnik, automatizacija ili odobrena AI aplikacija.','For supported actions, permissions, the version used and outcome records stay connected whether work starts with a user, automation or an approved AI application.'))+`<div class="control-paths"><div class="control-channel">${icon('user')}${tr('Korisnik u platformi','User in the platform')}</div><div class="control-channel">${icon('flow')}${tr('Automatizovani posao','Automated job')}</div><div class="control-channel">${icon('spark')}${tr('Odobrena AI aplikacija','Approved AI application')}</div></div><div class="control-grid">${controls.map((c,i)=>`<div class="control-step"><span class="index">0${i+1}</span><h3>${tr(c[0],c[1])}</h3><p>${tr(c[2],c[3])}</p><span class="control-proof">${tr(c[4],c[5])}</span></div>`).join('')}</div><div class="control-benefit"><strong>${tr('Jasan status i kada posao ne uspe.','A clear status when work does not succeed.')}</strong><p>${tr('Tim razlikuje završen posao, neuspešan pokušaj i nepoznat ishod. Dostupna evidencija i podržani postupci oporavka pomažu da se odredi sledeći korak bez slepog ponavljanja radnje.','The team distinguishes completed work, a failed attempt and an unknown outcome. Available evidence and supported recovery procedures help determine the next step without blindly repeating an action.')}</p></div><div class="meta-line"><span>${tr('Principi su zajednički; konkretne kontrole zavise od podržane radnje. To nije obećanje kontrole svih eksternih sistema niti dokaz tržišne isključivosti.','The principles are shared; specific controls depend on the supported action. This does not promise control of all external systems or establish market exclusivity.')}</span><button class="small-link" data-action="panel" data-value="controls">${tr('Dokazi, obuhvat i granice','Evidence, scope and boundaries')}${icon('arrow')}</button></div>`;}
function slide6(){return head(tr('06 / Poslovni model saradnje','06 / The partnership model'),tr('advanexus održava proizvod.<br><em>Partner uvodi rešenje kod klijenta.</em>','advanexus maintains the product.<br><em>The partner delivers the customer solution.</em>'),tr('Partner može da učestvuje u prodaji, implementaciji i podršci. Licenca, stručne usluge, troškovi i odgovornosti uređuju se posebnim dogovorom.','The partner can contribute to sales, implementation and support. The licence, professional services, costs and responsibilities are agreed separately.'))+`<div class="partner-business"><section class="partner-side"><h3>advanexus</h3><p>${tr('Razvoj i održavanje proizvoda','Product development and maintenance')}</p><ul><li>${tr('Povezane funkcionalnosti i kontrolni mehanizmi','Connected capabilities and control mechanisms')}</li><li>${tr('Dokumentacija i stručna podrška proizvodu','Product documentation and specialist support')}</li><li>${tr('Dogovor o potrebnim proširenjima proizvoda','Agreement on required product extensions')}</li></ul></section><section class="partner-side"><h3>${tr('Partner','The partner')}</h3><p>${tr('Rešenje za konkretan proces klijenta','A solution for a specific customer process')}</p><ul><li>${tr('Analiza, domenska pravila i kriterijumi uspeha','Discovery, domain rules and success criteria')}</li><li>${tr('Integracija, konfiguracija, obuka i uvođenje','Integration, configuration, training and adoption')}</li><li>${tr('Podrška i širenje primene prema dogovoru','Support and expansion within the agreed scope')}</li></ul></section></div><div class="partner-opportunities"><span>${tr('Zajednička prodaja','Joint selling')}</span><span>${tr('Implementacija','Implementation')}</span><span>${tr('Podrška i dalji razvoj primene','Support and expanded adoption')}</span></div><div class="commercial-grid"><div class="commercial-piece"><h4>${tr('Licenca proizvoda','Product licence')}</h4><p>${tr('Kompletna funkcionalnost, uključujući Intelligence.','Complete functionality, including Intelligence.')}</p></div><div class="commercial-piece"><h4>${tr('Stručne usluge','Professional services')}</h4><p>${tr('Uvođenje i prilagođavanje u ugovorenom obuhvatu.','Implementation and adaptation within an agreed scope.')}</p></div><div class="commercial-piece"><h4>${tr('Infrastruktura i AI','Infrastructure and AI')}</h4><p>${tr('Odvojeni troškovi okruženja i potrošnje.','Separate environment and consumption costs.')}</p></div><div class="commercial-piece"><h4>${tr('Odgovornost za klijenta','Customer accountability')}</h4><p>${tr('Ugovaranje, podrška, naknade i prava unapred se definišu.','Contracting, support, fees and rights are agreed upfront.')}</p></div></div><div class="meta-line"><span>${tr('Okvir za dogovor, ne unapred utvrđen partnerski program. Klijent potvrđuje pristup, poslovna pravila i prihvat rezultata.','A framework for agreement, not a pre-established partner programme. The customer approves access, business rules and acceptance.')}</span><button class="small-link" data-action="panel" data-value="delivery">${tr('Podela odgovornosti','Division of responsibilities')}${icon('arrow')}</button></div>`;}
function slide7(){return head(tr('07 / Proizvod i isporuka','07 / Product and delivery'),tr('Funkcionalnosti su razvijene.<br><em>Postavljanje u cloud je u toku.</em>','Product capabilities are developed.<br><em>Cloud deployment is in progress.</em>'),tr('Infrastrukturni angažman sa Mainstreamom, uz podršku AWS-a, završen je. Nakon postavljanja sledi završna funkcionalna provera u novom okruženju.','The infrastructure engagement with Mainstream, supported by AWS, is complete. A final functional test pass follows deployment in the new environment.'))+`<div class="status-layout"><div class="card product-now"><div class="small-label">${tr('Proizvod i odgovornost','Product and ownership')}</div><div class="product-fact">${icon('layers')}<div><strong>${tr('Povezani moduli','Connected modules')}</strong><p>${tr('Rad sa podacima, izvršavanje, provere, analitika i dostupna evidencija.','Data operations, execution, checks, analytics and available evidence.')}</p></div></div><div class="product-fact">${icon('target')}<div><strong>${tr('Pripremljeni demonstracioni scenariji','Prepared demonstration scenarios')}</strong><p>${tr('Bankarstvo i lanac snabdevanja; ilustrativni prikazi odvojeni su od stvarnih izvršenja.','Banking and supply chain; illustrations are distinguished from actual platform executions.')}</p></div></div><div class="founder"><img class="partner-founder-portrait" src="/static/pitch/founder-transparent.png" width="1254" height="1254" alt="Milovan Tomašević" loading="lazy"><div><strong>Milovan Tomašević, PhD</strong><p>Founder &amp; CEO · ${tr('Bankarski sistemi · inženjering podataka · primenjena istraživanja','Banking systems · data engineering · applied research')}</p></div></div></div><div class="timeline-card"><div class="partner-support-logos" aria-label="AWS · Mainstream"><img class="on-light" src="/static/industry/aws-on-light.svg" width="304" height="182" alt="AWS" loading="lazy"><img class="on-dark" src="/static/industry/aws-on-dark.png" width="59" height="35" alt="AWS" loading="lazy"><img class="partner-mainstream-logo" src="/static/alta/mainstream.png" width="800" height="154" alt="Mainstream" loading="lazy"></div><div class="timeline-row done"><span class="time-dot"></span><div class="small-label">${tr('Završeno / 2026','Completed / 2026')}</div><h3>${tr('Infrastrukturni angažman','Infrastructure engagement')}</h3><p>${tr('Angažman sa Mainstreamom, uz podršku AWS-a, završen je. Fokus je bio na infrastrukturi, skalabilnosti i pripremi za produkciju.','The Mainstream engagement, with AWS support, is complete. It focused on infrastructure, scalability and production preparation.')}</p></div><div class="timeline-row current"><span class="time-dot"></span><div class="small-label">${tr('U toku','In progress')}</div><h3>${tr('Postavljanje na sopstveni cloud','Deployment to advanexus’s own cloud')}</h3><p>${tr('Platforma se postavlja na sopstveni cloud za dalji razvoj i isporuku.','The platform is being deployed to its own cloud for continued development and delivery.')}</p></div><div class="timeline-row"><span class="time-dot"></span><div class="small-label">${tr('Sledi','Next')}</div><h3>${tr('Završno testiranje','Final testing')}</h3><p>${tr('Nakon postavljanja sledi završni funkcionalni prolaz i potvrda rezultata u novom okruženju.','Following deployment, a final functional test pass will verify results in the new environment.')}</p></div></div></div><div class="deployment-line"><span class="small-label">${tr('Opcije za dogovor','Deployment options to agree')}</span><span class="deploy-option">${icon('cloud')}advanexus cloud</span><span class="deploy-option">${icon('building')}${tr('Cloud klijenta','Customer cloud')}</span><span class="deploy-option">${icon('server')}On-premise</span><span>${tr('Svako okruženje zahteva poseban dogovor i potvrdu.','Each environment requires a specific agreement and validation.')}</span></div><div class="meta-line"><span>${tr('Status: 14. oktobar 2026. Podrška iz 2026. odnosi se na završeni infrastrukturni angažman. Prihvat novog okruženja sledi nakon testiranja.','As of 14 October 2026. Support in 2026 relates to the completed infrastructure engagement. Acceptance of the new environment follows testing.')}</span>${source('05 · 08')}</div>`;}
function slide8(){return `<div class="closing-head"><div class="eyebrow">${tr('08 / Sledeći korak','08 / The next step')}</div><h2>${tr('Prvi korak saradnje je konkretan:<br><em>jedan proces i dogovoren rezultat.</em>','The first step in working together:<br><em>one process and an agreed outcome.</em>')}</h2><p>${tr('Pregled proizvoda i primer klijenta služe da se dogovore obuhvat, odgovornosti i merilo uspeha pre odluke o zajedničkom angažmanu.','A product walkthrough and a customer case establish the scope, responsibilities and success criteria before a joint engagement is agreed.')}</p></div><div class="closing-cards"><a class="closing-card" href="${lang==='sr'?'/advanexus/bancs/demo/':'/advanexus/bancs/demo/en/'}" target="_blank" rel="noopener noreferrer">${icon('bank')}<h3>${tr('Bankarski primer','Banking example')}</h3><p>${tr('Pregled je pripremljen. Da li je spreman za upotrebu?','The report is prepared. Is it ready to use?')}</p><span class="card-action">${tr('Otvoriti vođeni demo','Open the guided demo')}${icon('arrow')}</span></a><a class="closing-card" href="${lang==='sr'?'/advanexus/scms/demo/':'/advanexus/scms/demo/en/'}" target="_blank" rel="noopener noreferrer">${icon('truck')}<h3>${tr('Lanac snabdevanja','Supply chain')}</h3><p>${tr('Isporuka je evidentirana. Šta još ostaje otvoreno?','Delivery is recorded. What is still unresolved?')}</p><span class="card-action">${tr('Otvoriti vođeni demo','Open the guided demo')}${icon('arrow')}</span></a><button class="closing-card primary" data-action="brief">${icon('target')}<h3>${tr('Definisati prvi<br>zajednički proces','Define the first<br>shared process')}</h3><p>${tr('Obuhvat, uloge i merljiv rezultat.','A defined scope, clear roles and a measurable outcome.')}</p><span class="card-action">${tr('Pripremiti sledeći razgovor','Prepare the next conversation')}${icon('arrow')}</span></button></div><div class="closing-contact"><div><div class="contact-name">Milovan Tomašević, PhD</div><div class="contact-role">Founder &amp; CEO · advanexus</div></div><div class="contact-links"><a href="mailto:mt@advanexus.com">mt@advanexus.com</a><a href="https://www.advanexus.com/demo-request/" target="_blank" rel="noopener noreferrer">${tr('Dogovoriti pregled','Arrange a walkthrough')} ↗</a></div></div><div class="meta-line" style="max-width:1120px;width:100%;align-self:center"><span>${tr('Vođeni primeri su ilustrativni. Stvarno izvršenje i rezultati platforme prikazuju se u zasebnoj demonstraciji.','Guided examples are illustrative. Actual platform execution and results are reviewed in a separate demonstration.')}</span><span>advanexus · ${tr('Partnerstva','Partner opportunities')} · 2026</span></div>`;}
function scenarioPanel(){return head(tr(' Od tehničkog uspeha do prihvatljivog rezultata',' From technical success to an accepted result'),tr('Obrada je završena.<br><em>Da li rezultat sme dalje?</em>','Processing is complete.<br><em>Is the result ready to proceed?</em>'),tr('Jedna obavezna provera povezuje podatke, ishod procesa i sledeći dozvoljeni korak.','One required check connects the data, process outcome and next permitted step.'))+`<div class="scenario-layout"><div class="scenario-panel" id="scenarioPanel">${scenarioInner()}</div><div class="scenario-aside" id="scenarioAside">${scenarioAside()}</div></div><div class="meta-line"><span>${tr('Ilustrativni scenario; nije ekran aplikacije ni živo izvršenje. Zaustavljanje važi za definisani tok. Automatska ispravka nije prikazana niti obećana.','Illustrative scenario; not an application screenshot or a live execution. The stop applies to the configured flow. Automatic repair is neither shown nor promised.')}</span>${source('04 · 06')}</div>`;}
function processPanel(){const steps=[
 ['Izabrati proces','Choose a process','Klijent, poslovni vlasnik i problem koji vredi rešiti.','A customer, an accountable owner and a problem worth solving.'],
 ['Dogovoriti obuhvat','Agree the scope','Izvori, dozvole, granice i očekivani rezultat.','Sources, permissions, boundaries and the expected outcome.'],
 ['Proveriti neizvesnost','Test uncertainty','Ciljani pilot samo kada postoji važno otvoreno pitanje.','A focused pilot only when an important open question needs testing.'],
 ['Uvesti i potvrditi','Implement and verify','Postaviti tok i proveriti dogovorene kriterijume.','Implement the workflow and test the agreed criteria.'],
 ['Predati i podržati','Hand over and support','Potvrditi odgovornosti, prihvat i podršku.','Confirm responsibilities, acceptance and support.']
 ];const measures=[['clock','Vreme do proverljivog odgovora','Time to a verifiable answer'],['search','Vreme istraživanja odstupanja','Time to investigate an exception'],['users','Preostali ručni koraci','Remaining manual steps'],['shield','Prolaz obaveznih provera','Required checks passed'],['history','Ponavljanje i dokaz rezultata','Repeatability and result evidence']];return head(tr(' Od razgovora do prve isporuke',' From a conversation to first delivery'),tr('Jedan zajednički proces.<br><em>Unapred dogovoren dokaz uspeha.</em>','One shared process.<br><em>Agree what success looks like.</em>'),tr('Početi od stvarnog posla klijenta, ne od najšireg mogućeg tehničkog obuhvata.','Start with the customer’s real work, not the widest possible technical scope.'))+`<div class="delivery-steps">${steps.map((s,i)=>`<div class="delivery-step ${i===2?'conditional':''}"><span class="step-index">0${i+1}</span><h3>${tr(s[0],s[1])}</h3><p>${tr(s[2],s[3])}</p></div>`).join('')}</div><div class="measure-panel"><div class="measure-head"><strong>${tr('Kako se meri rezultat','How outcomes are measured')}</strong><span>${tr('Početno stanje → dogovoreni cilj → proveren rezultat','Baseline → agreed target → verified outcome')}</span></div><div class="measure-grid">${measures.map(m=>`<div class="measure-item">${icon(m[0])}<span>${tr(m[1],m[2])}</span></div>`).join('')}</div></div><div class="delivery-foot"><p>${tr('Bez unapred obećanih procenata uštede. Poboljšanje se potvrđuje na dogovorenom procesu i istom mernom obuhvatu.','No promised savings percentages in advance. Improvement is verified against the agreed process and a consistent measurement scope.')}</p><button class="button" data-action="brief">${tr('Otvoriti radni list za proces','Open the process brief')}${icon('clipboard')}</button></div><div class="meta-line"><span>${tr('Pilot nije obavezan dodatni korak. Koristi se kada treba razrešiti stvarnu neizvesnost.','A pilot is not a mandatory extra step. Use it to resolve a genuine uncertainty.')}</span>${source('01')}</div>`;}

const slideFunctions=[slide1,slide2,slide3,slide4,slide5,slide6,slide7,slide8];
function slidesHtml(interactive=true){const cs=chapters();return slideFunctions.map((fn,i)=>`<article class="slide ${i===current?'active':''}" data-slide="slide-${i+1}" id="slide-${i+1}" aria-label="${i+1} / ${SLIDE_COUNT}: ${cs[i].label}" ${interactive&&!reading&&i!==current?'aria-hidden="true"':''}>${fn()}<div class="print-only">advanexus | ${tr('Partnerstva','Partner opportunities')}<span class="print-page">${String(i+1).padStart(2,'0')} / ${SLIDE_COUNT}</span></div></article>`).join('');}
function renderSlides(){$('#stage').innerHTML=slidesHtml();}
