function modulesPanel(){const labels=[tr('Sve','All'),tr('Povezati','Connect'),tr('Pripremiti','Prepare'),tr('Izvršiti i proveriti','Execute and check'),tr('Razumeti','Understand'),tr('Dokazati','Evidence'),tr('AI pristup','AI access'),tr('Podrška','Support')];const vals=['all','0','1','2','3','4','5','6'];const filtered=modules().filter(m=>moduleFilter==='all'||m.group===moduleFilter);return `<h3>${tr('Vrednost modula, povezana u celinu.','Module value, connected as a whole.')}</h3><p class="panel-lede">${tr('Otvorite modul za primer primene, rad partnera i granicu mogućnosti. Nazivi modula zadržani su radi prepoznavanja u proizvodu.','Open a module for its use case, partner opportunity and capability boundary. Module names are retained for recognition in the product.')}</p><div class="module-filter" role="group" aria-label="${tr('Filtriranje modula','Filter modules')}">${labels.map((l,i)=>`<button data-action="filter" data-value="${vals[i]}" aria-pressed="${moduleFilter===vals[i]}">${l}</button>`).join('')}</div>${filtered.map(m=>`<details class="module-card" id="module-${m.id}" ${highlightModule===m.id||filtered.length===1?'open':''}><summary>${icon(m.icon)}<div class="summary-copy"><h4>${m.name}</h4><p>${m.value}</p></div>${icon('plus','expand-icon')}</summary><div class="module-detail"><div class="module-rows"><div><h5>${tr('Prostor za rad partnera','Partner opportunity')}</h5><p>${m.partner}</p></div><div><h5>${tr('Primer primene','Example use')}</h5><p>${m.example}</p></div></div><p class="module-limit"><b>${tr('Granica mogućnosti.','Capability boundary.')}</b> ${m.limit}</p><a class="small-link" href="${m.url}" target="_blank" rel="noopener noreferrer">${tr('Javni opis i obuhvat','Public description and scope')}${icon('external')}</a></div></details>`).join('')}`;}
