function appendixHtml(){return `<div class="appendix-layout"><nav class="appendix-nav" role="tablist" aria-label="${tr('Teme dodatka','Appendix topics')}">${appendixTabs().map(t=>`<button role="tab" id="tab-${t[0]}" data-action="tab" data-value="${t[0]}" aria-selected="${appendixTab===t[0]}" aria-controls="appendixContent">${icon(t[1])}${t[2]}</button>`).join('')}<p class="nav-caption">${tr('Detalji ostaju izvan glavne prezentacije.','Details stay outside the main presentation.')}<br><br>advanexus · 2026</p></nav><section class="appendix-content" id="appendixContent" role="tabpanel" aria-labelledby="tab-${appendixTab}">${panelFns[appendixTab]()}</section></div>`;}
