function briefHtml(){return `<div class="dialog-body"><h3 class="case-main-title">${tr('Jedan proces. Dovoljno jasno za sledeći korak.','One process. Clear enough for the next step.')}</h3><p class="panel-lede">${tr('Popunite tokom razgovora. Izvozite lokalni sažetak; ova stranica ga ne šalje advanexus-u niti bilo kom drugom primaocu.','Complete this during the conversation. Export a local summary; this page sends nothing to advanexus or any other recipient.')}</p><form id="processForm" autocomplete="off"><div class="brief-grid">${briefFields().map(f=>`<div class="form-field"><label for="brief-${f[0]}">${f[1]}</label>${f[3]==='input'?`<input id="brief-${f[0]}" name="${f[0]}" placeholder="${f[2]}" value="${esc(brief[f[0]])}" maxlength="500">`:`<textarea id="brief-${f[0]}" name="${f[0]}" placeholder="${f[2]}" maxlength="2500">${esc(brief[f[0]])}</textarea>`}</div>`).join('')}</div></form><div class="brief-actions"><button class="button primary" data-action="download-brief">${icon('download')}${tr('Sačuvati sažetak (.txt)','Save the brief (.txt)')}</button><button class="button" data-action="copy-brief">${icon('copy')}${tr('Kopirati sažetak','Copy the brief')}</button><a class="button" href="https://www.advanexus.com/demo-request/" target="_blank" rel="noopener noreferrer">${tr('Dogovoriti razgovor','Arrange a conversation')}${icon('external')}</a></div><p class="brief-privacy">${tr('Podaci ostaju samo u memoriji ove stranice i brišu se njenim osvežavanjem ili zatvaranjem. Sačuvajte ili kopirajte sažetak pre zatvaranja. Koristite nazive uloga i ne unosite tajne ili osetljive podatke.','Data remains only in this page’s memory and is cleared on refresh or closure. Save or copy the brief before closing the page. Use role names and do not enter secrets or sensitive information.')}</p></div>`;}
let caseKind='bank';
function renderModal(){
 if(!modalType)return;
 const titles={overview:tr('Pregled prezentacije','Presentation overview'),appendix:tr('Detaljan partnerski pregled','A closer look for partners'),case:caseKind==='bank'?tr('Bankarstvo','Banking'):tr('Lanac snabdevanja','Supply chain'),brief:tr('Radni list za prvi proces','First-process brief')};
 const body=modalType==='overview'?overviewHtml():modalType==='appendix'?appendixHtml():modalType==='case'?caseHtml(caseKind):briefHtml();
 $('#detailDialog').innerHTML=`<div class="dialog-header"><div class="dialog-title"><span class="small-label">advanexus / ${tr('partnerstva','partner opportunities')}</span><h2 id="dialogTitle">${titles[modalType]}</h2></div><div class="dialog-tools"><button class="language" data-action="switch-lang" aria-label="${tr('English','Srpski')}" title="${tr('English','Srpski')}"><span class="language-flag" aria-hidden="true">${lang==='sr'?'🇬🇧':'🇷🇸'}</span></button><button class="icon-btn" data-action="theme" aria-label="${tr('Promeniti temu','Switch theme')}">${icon(theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-action="close" aria-label="${tr('Zatvori dodatni prikaz','Close the detail view')}">${icon('close')}</button></div></div>${body}`;
 $$('.appendix-nav [role=tab]').forEach(el=>el.tabIndex=el.getAttribute('aria-selected')==='true'?0:-1);
}
function openModal(type,value){
 saveBrief();stopPlaying();
 const dlg=$('#detailDialog');if(!dlg.open)lastFocus=document.activeElement;
 modalType=type;if(type==='case')caseKind=value||'bank';
 renderModal();if(!dlg.open)dlg.showModal();
 if(type==='appendix'&&highlightModule){const el=document.getElementById('module-'+highlightModule);if(el)el.scrollIntoView({block:'nearest'});}
}
function closeModal(){saveBrief();if($('#detailDialog').open)$('#detailDialog').close();}
function saveBrief(){if(!$('#processForm'))return;briefFields().forEach(f=>{const el=document.getElementById('brief-'+f[0]);if(el)brief[f[0]]=el.value;});}
function briefText(){saveBrief();return `advanexus | ${tr('Prvi zajednički proces','First shared process')}\n${tr('Radni sažetak za razgovor. Nije ponuda ni ugovor.','Working discussion brief. Not a quotation or contract.')}\n\n`+briefFields().map(f=>`${f[1]}\n${brief[f[0]].trim()||tr('[Za dogovor]','[To be agreed]')}`).join('\n\n')+`\n\n${tr('Sledeći korak: potvrditi obuhvat, odgovornosti i kriterijume uspeha.','Next step: confirm scope, responsibilities and acceptance criteria.')}\n\nmt@advanexus.com\nhttps://www.advanexus.com/\n`;}
function downloadBrief(){const blob=new Blob(['\uFEFF'+briefText()],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`advanexus-${lang==='sr'?'prvi-proces':'first-process'}-${lang}.txt`;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);showToast(tr('Sažetak je pripremljen za čuvanje.','The brief is ready to save.'));}
async function copyBrief(){const text=briefText();try{if(!navigator.clipboard||!window.isSecureContext)throw new Error('Clipboard fallback');await navigator.clipboard.writeText(text);showToast(tr('Sažetak je kopiran.','Brief copied.'));}catch{const a=document.createElement('textarea');a.value=text;a.setAttribute('readonly','');a.style.cssText='position:fixed;left:0;top:0;width:1px;height:1px;opacity:0';($('#detailDialog').open?$('#detailDialog'):document.body).appendChild(a);a.select();a.setSelectionRange(0,a.value.length);let ok=false;try{ok=document.execCommand('copy')}catch{}a.remove();showToast(ok?tr('Sažetak je kopiran.','Brief copied.'):tr('Kopiranje nije dostupno. Koristite „Sačuvati sažetak”.','Copying is unavailable. Use “Save the brief” instead.'));}}
function showToast(text){clearTimeout(toastTimer);if($('#detailDialog').open){let el=$('#dialogToast');if(!el){el=document.createElement('div');el.id='dialogToast';el.setAttribute('role','status');el.style.cssText='position:absolute;z-index:10;bottom:17px;left:20px;right:20px;padding:12px 17px;border:1px solid var(--accentLine);border-radius:10px;background:var(--surface2);color:var(--text);font-size:12px;box-shadow:var(--shadow);pointer-events:none';$('#detailDialog').appendChild(el);}el.textContent=text;toastTimer=setTimeout(()=>el.remove(),3000);}else{const el=$('#toast');el.textContent=text;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}}
function syncURL(){try{const u=new URL(location.href);u.hash=`slide-${current+1}`;u.searchParams.set('theme',theme);u.searchParams.delete('lang');if(reading)u.searchParams.set('view','reading');else u.searchParams.delete('view');if(/^\/static\/partners\/partners-(rs|en)\.html$/.test(u.pathname))u.pathname=`/static/partners/partners-${lang==='sr'?'rs':'en'}.html`;else if(/^\/advanexus\/partners(?:\/(?:rs|en))?\/?$/.test(u.pathname))u.pathname=`/advanexus/partners/${lang==='en'?'en/':''}`;else u.searchParams.set('lang',lang);history.replaceState(null,'',u);}catch{}}
function applyReading(){document.documentElement.classList.toggle('reading',reading);$$('.slide').forEach((el,i)=>{if(reading||i===current)el.removeAttribute('aria-hidden');else el.setAttribute('aria-hidden','true');});}
function go(index){const target=Number(index);if(!Number.isFinite(target))return;closeModal();stopPlaying();current=Math.min(SLIDE_COUNT-1,Math.max(0,target));$$('.slide').forEach((el,i)=>el.classList.toggle('active',i===current));applyReading();if(reading)$('#slide-'+(current+1)).scrollIntoView({block:'start'});else $('#stage').scrollTop=0;renderFooter();syncURL();$('#slideAnnouncement').textContent=tr(`Slajd ${current+1} od ${SLIDE_COUNT}. ${chapters()[current].label}`,`Slide ${current+1} of ${SLIDE_COUNT}. ${chapters()[current].label}`);}
function toggleReading(){reading=!reading;stopPlaying();applyReading();renderHeader();go(current);}
function setLanguage(value){if(!['sr','en'].includes(value))return;saveBrief();stopPlaying();const savedTop=$('#stage').scrollTop;lang=value;renderHeader();renderSlides();renderFooter();applyReading();if(modalType&&$('#detailDialog').open)renderModal();$('#stage').scrollTop=savedTop;syncURL();}
function toggleTheme(){saveBrief();theme=theme==='dark'?'light':'dark';renderHeader();if(modalType&&$('#detailDialog').open){const pos=$('#appendixContent')?.scrollTop||$('.dialog-body')?.scrollTop||0;renderModal();const sc=$('#appendixContent')||$('.dialog-body');if(sc)sc.scrollTop=pos;}syncURL();}
function updateScenario(){if($('#scenarioPanel'))$('#scenarioPanel').innerHTML=scenarioInner();if($('#scenarioAside'))$('#scenarioAside').innerHTML=scenarioAside();}
function stopPlaying(){if(playTimer){clearInterval(playTimer);playTimer=null;}if(playing){playing=false;updateScenario();}}
function setScenario(value){stopPlaying();scenario=Math.max(0,Math.min(2,Number(value)||0));updateScenario();}
function playScenario(){if(playing){stopPlaying();return;}if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){setScenario((scenario+1)%3);return;}playing=true;scenario=0;updateScenario();playTimer=setInterval(()=>{if(scenario<2){scenario++;updateScenario();}else stopPlaying();},3600);}
async function fullScreen(){try{if(document.fullscreenElement){await document.exitFullscreen();}else if(document.documentElement.requestFullscreen){await document.documentElement.requestFullscreen();}else if(document.documentElement.webkitRequestFullscreen){document.documentElement.webkitRequestFullscreen();}else showToast(tr('Ceo ekran nije dostupan u ovom pregledaču.','Full screen is not available in this browser.'));}catch{showToast(tr('Pregledač nije dozvolio ceo ekran.','The browser did not allow full screen.'));}}
function changeTab(value){if(!panelFns[value])return;appendixTab=value;highlightModule=null;renderModal();const el=$(`#tab-${value}`);if(el)el.focus({preventScroll:true});}
function printDeck(){closeModal();stopPlaying();setTimeout(()=>window.print(),100);}
if(inBrowser){
document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const {action,value}=el.dataset;
 if(el.tagName==='A'&&action==='switch-lang'&&(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey))return;
 if(el.tagName==='A')event.preventDefault();
 switch(action){
 case 'go':go(value);break;case 'previous':go(current-1);break;case 'next':go(current+1);break;
 case 'lang':setLanguage(value);break;case 'switch-lang':setLanguage(lang==='sr'?'en':'sr');break;case 'theme':toggleTheme();break;
 case 'overview':openModal('overview');break;case 'appendix':highlightModule=null;openModal('appendix');break;
 case 'references':appendixTab='references';highlightModule=null;openModal('appendix');break;
 case 'module-group':appendixTab='modules';moduleFilter=value;highlightModule=null;openModal('appendix');break;
 case 'module':{const m=modules().find(m=>m.id===value);if(m){appendixTab='modules';moduleFilter=m.group;highlightModule=value;openModal('appendix');}break;}
 case 'tab':changeTab(value);break;
 case 'vendor':selectVendor(value);break;
 case 'compare-tab':selectComparison(value);break;
 case 'panel':if(panelFns[value]){appendixTab=value;highlightModule=null;openModal('appendix');}break;
 case 'filter':{moduleFilter=value;highlightModule=null;const content=$('#appendixContent');content.innerHTML=modulesPanel();const b=content.querySelector(`[data-action="filter"][data-value="${value}"]`);if(b)b.focus({preventScroll:true});break;}
 case 'case':openModal('case',value);break;case 'brief':openModal('brief');break;case 'close':closeModal();break;
 case 'download-brief':downloadBrief();break;case 'copy-brief':copyBrief();break;case 'scenario':setScenario(value);break;case 'play':playScenario();break;
 case 'fullscreen':fullScreen();break;case 'print':printDeck();break;case 'reading':toggleReading();break;
 }
});
document.addEventListener('input',event=>{const el=event.target;if(el.closest('#processForm')&&Object.hasOwn(brief,el.name))brief[el.name]=el.value;});
document.addEventListener('submit',event=>{if(event.target.id==='processForm')event.preventDefault();});
$('#detailDialog').addEventListener('close',()=>{modalType=null;highlightModule=null;if(lastFocus&&document.contains(lastFocus))lastFocus.focus({preventScroll:true});lastFocus=null;});
$('#detailDialog').addEventListener('click',event=>{if(event.target!==$('#detailDialog'))return;const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();});
document.addEventListener('keydown',event=>{
 if(event.metaKey||event.ctrlKey||event.altKey)return;
 const target=event.target;const editing=target.matches('input,textarea,select,[contenteditable="true"]');
 if($('#detailDialog').open){
  if(target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key)){
   event.preventDefault();const ts=appendixTabs();let i=ts.findIndex(t=>t[0]===appendixTab);if(event.key==='Home')i=0;else if(event.key==='End')i=ts.length-1;else i=(i+(['ArrowRight','ArrowDown'].includes(event.key)?1:-1)+ts.length)%ts.length;changeTab(ts[i][0]);
  }return;
 }
 if(editing)return;
 if(target.matches('[data-action="compare-tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){
  event.preventDefault();const next=event.key==='Home'?'map':event.key==='End'?'matrix':comparisonTab==='map'?'matrix':'map';selectComparison(next);$('#partner-tab-'+next).focus();return;
 }
 const k=event.key.toLowerCase();
 if(['ArrowRight','PageDown'].includes(event.key)){event.preventDefault();go(current+1);}
 else if(['ArrowLeft','PageUp'].includes(event.key)){event.preventDefault();go(current-1);}
 else if(event.key===' '&&!target.closest('button,a,summary')){event.preventDefault();go(current+(event.shiftKey?-1:1));}
 else if(event.key==='Home'){event.preventDefault();go(0);}
 else if(event.key==='End'){event.preventDefault();go(SLIDE_COUNT-1);}
 else if(k==='o'||k==='?'){event.preventDefault();openModal('overview');}
 else if(k==='a'){event.preventDefault();openModal('appendix');}
 else if(k==='l'){event.preventDefault();setLanguage(lang==='sr'?'en':'sr');}
 else if(k==='t'){event.preventDefault();toggleTheme();}
 else if(k==='f'){event.preventDefault();fullScreen();}
 else if(k==='r'){event.preventDefault();toggleReading();}
 else if(/^[1-9]$/.test(k)&&Number(k)<=SLIDE_COUNT){event.preventDefault();go(Number(k)-1);}
});
let swipeStart=null;
$('#stage').addEventListener('touchstart',event=>{if(event.touches.length===1&&!$('#detailDialog').open&&!event.target.closest('button,a,input,textarea,summary,.partner-map-scroll,.detail-table-wrap'))swipeStart={x:event.touches[0].clientX,y:event.touches[0].clientY,time:performance.now()};else swipeStart=null;},{passive:true});
$('#stage').addEventListener('touchend',event=>{if(reading||!swipeStart||!event.changedTouches.length)return;const d=event.changedTouches[0],dx=d.clientX-swipeStart.x,dy=d.clientY-swipeStart.y,dt=performance.now()-swipeStart.time;swipeStart=null;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.7&&dt<850)go(current+(dx<0?1:-1));},{passive:true});
window.addEventListener('hashchange',()=>{const v=parseInt(location.hash.replace(/^#\/?slide-/,''),10);if(v>=1&&v<=SLIDE_COUNT&&v-1!==current)go(v-1);});
window.addEventListener('beforeprint',()=>{stopPlaying();});
window.addEventListener('pagehide',()=>stopPlaying());
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPlaying();});
renderHeader();renderSlides();renderFooter();document.documentElement.classList.add('enhanced');applyReading();syncURL();
}else if(typeof module!=='undefined'){
 module.exports={renderStatic(locale,vendors=[]){vendorData=vendors;lang=locale==='en'?'en':'sr';return {slides:slidesHtml(false),modules:modulesPanel()};}};
}
